  } else {
    if (labelMetrics_.count(labelId)) {
      ret = labelMetrics_.at(labelId).scoreVsTrue;
    }
  }
  std::sort(
      ret.begin(),
      ret.end(),
      [](const std::pair<real, real>& l, const std::pair<real, real>& r) {
        return l.first < r.first;
      });

  return ret;
}

