    int dsub,
    int64_t fileSize) const {
  int32_t outM = fastText_->getOutputMatrix()->size(0);
  int32_t outN = fastText_->getOutputMatrix()->size(1);
  int32_t dim = fastText_->getDimension();
  int32_t nlabels = fastText_->getDictionary()->nlabels();
  int32_t nwords = fastText_->getDictionary()->nwords();

  // size of the output matrix (dense or quantized)
  int64_t outSize = 0;
  if (qout) {
    outSize = sizeof(bool) + 2 * sizeof(int64_t) + sizeof(int32_t) +
        (int64_t)outM * ((outN + 2 - 1) / 2) * sizeof(uint8_t) +
        4 * sizeof(int32_t) + (int64_t)outN * (1 << 8) * sizeof(real);
    if (qnorm) {
      outSize += (int64_t)outM * sizeof(uint8_t) + 4 * sizeof(int32_t) +
          (1 << 8) * sizeof(real);
    }
  } else {
    outSize = 2 * sizeof(int64_t) + (int64_t)outM * outN * sizeof(real);
  }

  // fixed costs: magic + version, args, dictionary header, flags,
  // quantized input matrix header and codebooks.
  int64_t currentSize = 2 * sizeof(int32_t) + 12 * sizeof(int32_t) +
      sizeof(double) + 3 * sizeof(int32_t) + 2 * sizeof(int64_t) +
      2 * sizeof(bool) + sizeof(bool) + 2 * sizeof(int64_t) +
      sizeof(int32_t) + 4 * sizeof(int32_t) +
      (int64_t)dim * (1 << 8) * sizeof(real) + outSize;
  if (qnorm) {
    currentSize += 4 * sizeof(int32_t) + (1 << 8) * sizeof(real);
  }
  // dictionary entries for labels
  for (int32_t i = 0; i < nlabels; i++) {
    std::string label = fastText_->getDictionary()->getLabel(i);
    currentSize += label.size() + 1 + sizeof(int64_t) + sizeof(int8_t);
  }
  // average dictionary entry size for words
  int64_t wordsSize = 0;
  for (int32_t i = 0; i < nwords; i++) {
    std::string word = fastText_->getDictionary()->getWord(i);
    wordsSize += word.size() + 1 + sizeof(int64_t) + sizeof(int8_t);
  }
  int64_t meanWordSize = nwords > 0 ? (wordsSize + nwords - 1) / nwords : 0;

  // per row costs
  int64_t perRowSize = ((dim + dsub - 1) / dsub) * sizeof(uint8_t);
  if (qnorm) {
    perRowSize += sizeof(uint8_t);
  }
  int64_t perWordRow = perRowSize + meanWordSize;
  int64_t perNgramRow = perRowSize + 2 * sizeof(int32_t);

  int64_t remaining = fileSize - currentSize;
  int64_t cutoff = 0;
  if (remaining > 0) {
    if (remaining <= (int64_t)nwords * perWordRow) {
      cutoff = remaining / perWordRow;
    } else {
      cutoff = nwords + (remaining - (int64_t)nwords * perWordRow) / perNgramRow;
    }
  }
  if (cutoff < kCutoffLimit) {
    cutoff = kCutoffLimit;
  }
  if (cutoff > std::numeric_limits<int>::max()) {
    cutoff = std::numeric_limits<int>::max();
  }
  return static_cast<int>(cutoff);
}

